mkitem!{pub (crate) type UnificationTable < 'a , 'tcx , T > = ut :: UnificationTable < ut :: InPlace < T , & 'a mut ut :: UnificationStorage < T > , & 'a mut InferCtxtUndoLogs < 'tcx > > , > ;}
mkitem!{mkstruct!{# [doc = " This type contains all the things within `InferCtxt` that sit within a"] # [doc = " `RefCell` and are involved with taking/rolling back snapshots. Snapshot"] # [doc = " operations are hot enough that we want only one call to `borrow_mut` per"] # [doc = " call to `start_snapshot` and `rollback_to`."] # [derive (Clone)] pub struct InferCtxtInner < 'tcx > { undo_log : InferCtxtUndoLogs < 'tcx > , # [doc = " Cache for projections."] # [doc = ""] # [doc = " This cache is snapshotted along with the infcx."] projection_cache : traits :: ProjectionCacheStorage < 'tcx > , # [doc = " We instantiate `UnificationTable` with `bounds<Ty>` because the types"] # [doc = " that might instantiate a general type variable have an order,"] # [doc = " represented by its upper and lower bounds."] type_variable_storage : type_variable :: TypeVariableStorage < 'tcx > , # [doc = " Map from const parameter variable to the kind of const it represents."] const_unification_storage : ut :: UnificationTableStorage < ConstVidKey < 'tcx > > , # [doc = " Map from integral variable to the kind of integer it represents."] int_unification_storage : ut :: UnificationTableStorage < ty :: IntVid > , # [doc = " Map from floating variable to the kind of float it represents."] float_unification_storage : ut :: UnificationTableStorage < ty :: FloatVid > , # [doc = " Tracks the set of region variables and the constraints between them."] # [doc = ""] # [doc = " This is initially `Some(_)` but when"] # [doc = " `resolve_regions_and_report_errors` is invoked, this gets set to `None`"] # [doc = " -- further attempts to perform unification, etc., may fail if new"] # [doc = " region constraints would've been added."] region_constraint_storage : Option < RegionConstraintStorage < 'tcx > > , # [doc = " A set of constraints that regionck must validate."] # [doc = ""] # [doc = " Each constraint has the form `T:'a`, meaning \"some type `T` must"] # [doc = " outlive the lifetime 'a\". These constraints derive from"] # [doc = " instantiated type parameters. So if you had a struct defined"] # [doc = " like the following:"] # [doc = " ```ignore (illustrative)"] # [doc = " struct Foo<T: 'static> { ... }"] # [doc = " ```"] # [doc = " In some expression `let x = Foo { ... }`, it will"] # [doc = " instantiate the type parameter `T` with a fresh type `$0`. At"] # [doc = " the same time, it will record a region obligation of"] # [doc = " `$0: 'static`. This will get checked later by regionck. (We"] # [doc = " can't generally check these things right away because we have"] # [doc = " to wait until types are resolved.)"] # [doc = ""] # [doc = " These are stored in a map keyed to the id of the innermost"] # [doc = " enclosing fn body / static initializer expression. This is"] # [doc = " because the location where the obligation was incurred can be"] # [doc = " relevant with respect to which sublifetime assumptions are in"] # [doc = " place. The reason that we store under the fn-id, and not"] # [doc = " something more fine-grained, is so that it is easier for"] # [doc = " regionck to be sure that it has found *all* the region"] # [doc = " obligations (otherwise, it's easy to fail to walk to a"] # [doc = " particular node-id)."] # [doc = ""] # [doc = " Before running `resolve_regions_and_report_errors`, the creator"] # [doc = " of the inference context is expected to invoke"] # [doc = " [`InferCtxt::process_registered_region_obligations`]"] # [doc = " for each body-id in this map, which will process the"] # [doc = " obligations within. This is expected to be done 'late enough'"] # [doc = " that all type inference variables have been bound and so forth."] region_obligations : Vec < TypeOutlivesConstraint < 'tcx > > , # [doc = " The outlives bounds that we assume must hold about placeholders that"] # [doc = " come from instantiating the binder of coroutine-witnesses. These bounds"] # [doc = " are deduced from the well-formedness of the witness's types, and are"] # [doc = " necessary because of the way we anonymize the regions in a coroutine,"] # [doc = " which may cause types to no longer be considered well-formed."] region_assumptions : Vec < ty :: ArgOutlivesPredicate < 'tcx > > , # [doc = " `-Znext-solver`: Successfully proven goals during HIR typeck which"] # [doc = " reference inference variables and get reproven in case MIR type check"] # [doc = " fails to prove something."] # [doc = ""] # [doc = " See the documentation of `InferCtxt::in_hir_typeck` for more details."] hir_typeck_potentially_region_dependent_goals : Vec < PredicateObligation < 'tcx > > , # [doc = " Caches for opaque type inference."] opaque_type_storage : OpaqueTypeStorage < 'tcx > , }}}
mkitem!{mkimpl!{impl < 'tcx > InferCtxtInner < 'tcx > { fn new () -> InferCtxtInner < 'tcx > { InferCtxtInner { undo_log : InferCtxtUndoLogs :: default () , projection_cache : Default :: default () , type_variable_storage : Default :: default () , const_unification_storage : Default :: default () , int_unification_storage : Default :: default () , float_unification_storage : Default :: default () , region_constraint_storage : Some (Default :: default ()) , region_obligations : Default :: default () , region_assumptions : Default :: default () , hir_typeck_potentially_region_dependent_goals : Default :: default () , opaque_type_storage : Default :: default () , } } # [inline] pub fn region_obligations (& self) -> & [TypeOutlivesConstraint < 'tcx >] { & self . region_obligations } # [inline] pub fn region_assumptions (& self) -> & [ty :: ArgOutlivesPredicate < 'tcx >] { & self . region_assumptions } # [inline] pub fn projection_cache (& mut self) -> traits :: ProjectionCache < '_ , 'tcx > { self . projection_cache . with_log (& mut self . undo_log) } # [inline] fn try_type_variables_probe_ref (& self , vid : ty :: TyVid ,) -> Option < & type_variable :: TypeVariableValue < 'tcx > > { self . type_variable_storage . eq_relations_ref () . try_probe_value (vid) } # [inline] fn type_variables (& mut self) -> type_variable :: TypeVariableTable < '_ , 'tcx > { self . type_variable_storage . with_log (& mut self . undo_log) } # [inline] pub fn opaque_types (& mut self) -> opaque_types :: OpaqueTypeTable < '_ , 'tcx > { self . opaque_type_storage . with_log (& mut self . undo_log) } # [inline] fn int_unification_table (& mut self) -> UnificationTable < '_ , 'tcx , ty :: IntVid > { self . int_unification_storage . with_log (& mut self . undo_log) } # [inline] fn float_unification_table (& mut self) -> UnificationTable < '_ , 'tcx , ty :: FloatVid > { self . float_unification_storage . with_log (& mut self . undo_log) } # [inline] fn const_unification_table (& mut self) -> UnificationTable < '_ , 'tcx , ConstVidKey < 'tcx > > { self . const_unification_storage . with_log (& mut self . undo_log) } # [inline] pub fn unwrap_region_constraints (& mut self) -> RegionConstraintCollector < '_ , 'tcx > { self . region_constraint_storage . as_mut () . expect ("region constraints already solved") . with_log (& mut self . undo_log) } }}}
mkitem!{mkstruct!{pub struct InferCtxt < 'tcx > { pub tcx : TyCtxt < 'tcx > , # [doc = " The mode of this inference context, see the struct documentation"] # [doc = " for more details."] typing_mode : TypingMode < 'tcx > , # [doc = " Whether this inference context should care about region obligations in"] # [doc = " the root universe. Most notably, this is used during HIR typeck as region"] # [doc = " solving is left to borrowck instead."] pub considering_regions : bool , # [doc = " `-Znext-solver`: Whether this inference context is used by HIR typeck. If so, we"] # [doc = " need to make sure we don't rely on region identity in the trait solver or when"] # [doc = " relating types. This is necessary as borrowck starts by replacing each occurrence of a"] # [doc = " free region with a unique inference variable. If HIR typeck ends up depending on two"] # [doc = " regions being equal we'd get unexpected mismatches between HIR typeck and MIR typeck,"] # [doc = " resulting in an ICE."] # [doc = ""] # [doc = " The trait solver sometimes depends on regions being identical. As a concrete example"] # [doc = " the trait solver ignores other candidates if one candidate exists without any constraints."] # [doc = " The goal `&'a u32: Equals<&'a u32>` has no constraints right now. If we replace each"] # [doc = " occurrence of `'a` with a unique region the goal now equates these regions. See"] # [doc = " the tests in trait-system-refactor-initiative#27 for concrete examples."] # [doc = ""] # [doc = " We handle this by *uniquifying* region when canonicalizing root goals during HIR typeck."] # [doc = " This is still insufficient as inference variables may *hide* region variables, so e.g."] # [doc = " `dyn TwoSuper<?x, ?x>: Super<?x>` may hold but MIR typeck could end up having to prove"] # [doc = " `dyn TwoSuper<&'0 (), &'1 ()>: Super<&'2 ()>` which is now ambiguous. Because of this we"] # [doc = " stash all successfully proven goals which reference inference variables and then reprove"] # [doc = " them after writeback."] pub in_hir_typeck : bool , # [doc = " If set, this flag causes us to skip the 'leak check' during"] # [doc = " higher-ranked subtyping operations. This flag is a temporary one used"] # [doc = " to manage the removal of the leak-check: for the time being, we still run the"] # [doc = " leak-check, but we issue warnings."] skip_leak_check : bool , pub inner : RefCell < InferCtxtInner < 'tcx > > , # [doc = " Once region inference is done, the values for each variable."] lexical_region_resolutions : RefCell < Option < LexicalRegionResolutions < 'tcx > > > , # [doc = " Caches the results of trait selection. This cache is used"] # [doc = " for things that depends on inference variables or placeholders."] pub selection_cache : select :: SelectionCache < 'tcx , ty :: ParamEnv < 'tcx > > , # [doc = " Caches the results of trait evaluation. This cache is used"] # [doc = " for things that depends on inference variables or placeholders."] pub evaluation_cache : select :: EvaluationCache < 'tcx , ty :: ParamEnv < 'tcx > > , # [doc = " The set of predicates on which errors have been reported, to"] # [doc = " avoid reporting the same error twice."] pub reported_trait_errors : RefCell < FxIndexMap < Span , (Vec < Goal < 'tcx , ty :: Predicate < 'tcx > > > , ErrorGuaranteed) > > , pub reported_signature_mismatch : RefCell < FxHashSet < (Span , Option < Span >) > > , # [doc = " When an error occurs, we want to avoid reporting \"derived\""] # [doc = " errors that are due to this original failure. We have this"] # [doc = " flag that one can set whenever one creates a type-error that"] # [doc = " is due to an error in a prior pass."] # [doc = ""] # [doc = " Don't read this flag directly, call `is_tainted_by_errors()`"] # [doc = " and `set_tainted_by_errors()`."] tainted_by_errors : Cell < Option < ErrorGuaranteed > > , # [doc = " What is the innermost universe we have created? Starts out as"] # [doc = " `UniverseIndex::root()` but grows from there as we enter"] # [doc = " universal quantifiers."] # [doc = ""] # [doc = " N.B., at present, we exclude the universal quantifiers on the"] # [doc = " item we are type-checking, and just consider those names as"] # [doc = " part of the root universe. So this would only get incremented"] # [doc = " when we enter into a higher-ranked (`for<..>`) type or trait"] # [doc = " bound."] universe : Cell < ty :: UniverseIndex > , next_trait_solver : bool , pub obligation_inspector : Cell < Option < ObligationInspector < 'tcx > > > , }}}
mkitem!{mkenum!{# [doc = " See the `error_reporting` module for more details."] # [derive (Clone , Copy , Debug , PartialEq , Eq , TypeFoldable , TypeVisitable)] pub enum ValuePairs < 'tcx > { Regions (ExpectedFound < ty :: Region < 'tcx > >) , Terms (ExpectedFound < ty :: Term < 'tcx > >) , Aliases (ExpectedFound < ty :: AliasTerm < 'tcx > >) , TraitRefs (ExpectedFound < ty :: TraitRef < 'tcx > >) , PolySigs (ExpectedFound < ty :: PolyFnSig < 'tcx > >) , ExistentialTraitRef (ExpectedFound < ty :: PolyExistentialTraitRef < 'tcx > >) , ExistentialProjection (ExpectedFound < ty :: PolyExistentialProjection < 'tcx > >) , }}}
