mkitem!{mkimpl!{impl < 'tcx > InferCtxt < 'tcx > { pub fn dcx (& self) -> DiagCtxtHandle < '_ > { self . tcx . dcx () . taintable_handle (& self . tainted_by_errors) } pub fn next_trait_solver (& self) -> bool { self . next_trait_solver } # [inline (always)] pub fn typing_mode (& self) -> TypingMode < 'tcx > { self . typing_mode } pub fn freshen < T : TypeFoldable < TyCtxt < 'tcx > > > (& self , t : T) -> T { t . fold_with (& mut self . freshener ()) } # [doc = " Returns the origin of the type variable identified by `vid`."] # [doc = ""] # [doc = " No attempt is made to resolve `vid` to its root variable."] pub fn type_var_origin (& self , vid : TyVid) -> TypeVariableOrigin { self . inner . borrow_mut () . type_variables () . var_origin (vid) } # [doc = " Returns the origin of the const variable identified by `vid`"] pub fn const_var_origin (& self , vid : ConstVid) -> Option < ConstVariableOrigin > { match self . inner . borrow_mut () . const_unification_table () . probe_value (vid) { ConstVariableValue :: Known { .. } => None , ConstVariableValue :: Unknown { origin , .. } => Some (origin) , } } pub fn freshener < 'b > (& 'b self) -> TypeFreshener < 'b , 'tcx > { freshen :: TypeFreshener :: new (self) } pub fn unresolved_variables (& self) -> Vec < Ty < 'tcx > > { let mut inner = self . inner . borrow_mut () ; let mut vars : Vec < Ty < '_ > > = inner . type_variables () . unresolved_variables () . into_iter () . map (| t | Ty :: new_var (self . tcx , t)) . collect () ; vars . extend ((0 .. inner . int_unification_table () . len ()) . map (| i | ty :: IntVid :: from_usize (i)) . filter (| & vid | inner . int_unification_table () . probe_value (vid) . is_unknown ()) . map (| v | Ty :: new_int_var (self . tcx , v)) ,) ; vars . extend ((0 .. inner . float_unification_table () . len ()) . map (| i | ty :: FloatVid :: from_usize (i)) . filter (| & vid | inner . float_unification_table () . probe_value (vid) . is_unknown ()) . map (| v | Ty :: new_float_var (self . tcx , v)) ,) ; vars } # [instrument (skip (self) , level = "debug")] pub fn sub_regions (& self , origin : SubregionOrigin < 'tcx > , a : ty :: Region < 'tcx > , b : ty :: Region < 'tcx > ,) { self . inner . borrow_mut () . unwrap_region_constraints () . make_subregion (origin , a , b) ; } # [doc = " Processes a `Coerce` predicate from the fulfillment context."] # [doc = " This is NOT the preferred way to handle coercion, which is to"] # [doc = " invoke `FnCtxt::coerce` or a similar method (see `coercion.rs`)."] # [doc = ""] # [doc = " This method here is actually a fallback that winds up being"] # [doc = " invoked when `FnCtxt::coerce` encounters unresolved type variables"] # [doc = " and records a coercion predicate. Presently, this method is equivalent"] # [doc = " to `subtype_predicate` -- that is, \"coercing\" `a` to `b` winds up"] # [doc = " actually requiring `a <: b`. This is of course a valid coercion,"] # [doc = " but it's not as flexible as `FnCtxt::coerce` would be."] # [doc = ""] # [doc = " (We may refactor this in the future, but there are a number of"] # [doc = " practical obstacles. Among other things, `FnCtxt::coerce` presently"] # [doc = " records adjustments that are required on the HIR in order to perform"] # [doc = " the coercion, and we don't currently have a way to manage that.)"] pub fn coerce_predicate (& self , cause : & ObligationCause < 'tcx > , param_env : ty :: ParamEnv < 'tcx > , predicate : ty :: PolyCoercePredicate < 'tcx > ,) -> Result < InferResult < 'tcx , () > , (TyVid , TyVid) > { let subtype_predicate = predicate . map_bound (| p | ty :: SubtypePredicate { a_is_expected : false , a : p . a , b : p . b , }) ; self . subtype_predicate (cause , param_env , subtype_predicate) } pub fn subtype_predicate (& self , cause : & ObligationCause < 'tcx > , param_env : ty :: ParamEnv < 'tcx > , predicate : ty :: PolySubtypePredicate < 'tcx > ,) -> Result < InferResult < 'tcx , () > , (TyVid , TyVid) > { let r_a = self . shallow_resolve (predicate . skip_binder () . a) ; let r_b = self . shallow_resolve (predicate . skip_binder () . b) ; match (r_a . kind () , r_b . kind ()) { (& ty :: Infer (ty :: TyVar (a_vid)) , & ty :: Infer (ty :: TyVar (b_vid))) => { self . sub_unify_ty_vids_raw (a_vid , b_vid) ; return Err ((a_vid , b_vid)) ; } _ => { } } self . enter_forall (predicate , | ty :: SubtypePredicate { a_is_expected , a , b } | { if a_is_expected { Ok (self . at (cause , param_env) . sub (DefineOpaqueTypes :: Yes , a , b)) } else { Ok (self . at (cause , param_env) . sup (DefineOpaqueTypes :: Yes , b , a)) } }) } # [doc = " Number of type variables created so far."] pub fn num_ty_vars (& self) -> usize { self . inner . borrow_mut () . type_variables () . num_vars () } pub fn next_ty_vid (& self , span : Span) -> TyVid { self . next_ty_vid_with_origin (TypeVariableOrigin { span , param_def_id : None }) } pub fn next_ty_vid_with_origin (& self , origin : TypeVariableOrigin) -> TyVid { self . inner . borrow_mut () . type_variables () . new_var (self . universe () , origin) } pub fn next_ty_vid_in_universe (& self , span : Span , universe : ty :: UniverseIndex) -> TyVid { let origin = TypeVariableOrigin { span , param_def_id : None } ; self . inner . borrow_mut () . type_variables () . new_var (universe , origin) } pub fn next_ty_var (& self , span : Span) -> Ty < 'tcx > { self . next_ty_var_with_origin (TypeVariableOrigin { span , param_def_id : None }) } pub fn next_ty_var_with_origin (& self , origin : TypeVariableOrigin) -> Ty < 'tcx > { let vid = self . next_ty_vid_with_origin (origin) ; Ty :: new_var (self . tcx , vid) } pub fn next_ty_var_in_universe (& self , span : Span , universe : ty :: UniverseIndex) -> Ty < 'tcx > { let vid = self . next_ty_vid_in_universe (span , universe) ; Ty :: new_var (self . tcx , vid) } pub fn next_const_var (& self , span : Span) -> ty :: Const < 'tcx > { self . next_const_var_with_origin (ConstVariableOrigin { span , param_def_id : None }) } pub fn next_const_var_with_origin (& self , origin : ConstVariableOrigin) -> ty :: Const < 'tcx > { let vid = self . inner . borrow_mut () . const_unification_table () . new_key (ConstVariableValue :: Unknown { origin , universe : self . universe () }) . vid ; ty :: Const :: new_var (self . tcx , vid) } pub fn next_const_var_in_universe (& self , span : Span , universe : ty :: UniverseIndex ,) -> ty :: Const < 'tcx > { let origin = ConstVariableOrigin { span , param_def_id : None } ; let vid = self . inner . borrow_mut () . const_unification_table () . new_key (ConstVariableValue :: Unknown { origin , universe }) . vid ; ty :: Const :: new_var (self . tcx , vid) } pub fn next_int_var (& self) -> Ty < 'tcx > { let next_int_var_id = self . inner . borrow_mut () . int_unification_table () . new_key (ty :: IntVarValue :: Unknown) ; Ty :: new_int_var (self . tcx , next_int_var_id) } pub fn next_float_var (& self) -> Ty < 'tcx > { let next_float_var_id = self . inner . borrow_mut () . float_unification_table () . new_key (ty :: FloatVarValue :: Unknown) ; Ty :: new_float_var (self . tcx , next_float_var_id) } # [doc = " Creates a fresh region variable with the next available index."] # [doc = " The variable will be created in the maximum universe created"] # [doc = " thus far, allowing it to name any region created thus far."] pub fn next_region_var (& self , origin : RegionVariableOrigin) -> ty :: Region < 'tcx > { self . next_region_var_in_universe (origin , self . universe ()) } # [doc = " Creates a fresh region variable with the next available index"] # [doc = " in the given universe; typically, you can use"] # [doc = " `next_region_var` and just use the maximal universe."] pub fn next_region_var_in_universe (& self , origin : RegionVariableOrigin , universe : ty :: UniverseIndex ,) -> ty :: Region < 'tcx > { let region_var = self . inner . borrow_mut () . unwrap_region_constraints () . new_region_var (universe , origin) ; ty :: Region :: new_var (self . tcx , region_var) } pub fn next_term_var_of_kind (& self , term : ty :: Term < 'tcx > , span : Span) -> ty :: Term < 'tcx > { match term . kind () { ty :: TermKind :: Ty (_) => self . next_ty_var (span) . into () , ty :: TermKind :: Const (_) => self . next_const_var (span) . into () , } } # [doc = " Return the universe that the region `r` was created in. For"] # [doc = " most regions (e.g., `'static`, named regions from the user,"] # [doc = " etc) this is the root universe U0. For inference variables or"] # [doc = " placeholders, however, it will return the universe which they"] # [doc = " are associated."] pub fn universe_of_region (& self , r : ty :: Region < 'tcx >) -> ty :: UniverseIndex { self . inner . borrow_mut () . unwrap_region_constraints () . universe (r) } # [doc = " Number of region variables created so far."] pub fn num_region_vars (& self) -> usize { self . inner . borrow_mut () . unwrap_region_constraints () . num_region_vars () } # [doc = " Just a convenient wrapper of `next_region_var` for using during NLL."] # [instrument (skip (self) , level = "debug")] pub fn next_nll_region_var (& self , origin : NllRegionVariableOrigin) -> ty :: Region < 'tcx > { self . next_region_var (RegionVariableOrigin :: Nll (origin)) } # [doc = " Just a convenient wrapper of `next_region_var` for using during NLL."] # [instrument (skip (self) , level = "debug")] pub fn next_nll_region_var_in_universe (& self , origin : NllRegionVariableOrigin , universe : ty :: UniverseIndex ,) -> ty :: Region < 'tcx > { self . next_region_var_in_universe (RegionVariableOrigin :: Nll (origin) , universe) } pub fn var_for_def (& self , span : Span , param : & ty :: GenericParamDef) -> GenericArg < 'tcx > { match param . kind { GenericParamDefKind :: Lifetime => { self . next_region_var (RegionVariableOrigin :: RegionParameterDefinition (span , param . name ,)) . into () } GenericParamDefKind :: Type { .. } => { let ty_var_id = self . inner . borrow_mut () . type_variables () . new_var (self . universe () , TypeVariableOrigin { param_def_id : Some (param . def_id) , span } ,) ; Ty :: new_var (self . tcx , ty_var_id) . into () } GenericParamDefKind :: Const { .. } => { let origin = ConstVariableOrigin { param_def_id : Some (param . def_id) , span } ; let const_var_id = self . inner . borrow_mut () . const_unification_table () . new_key (ConstVariableValue :: Unknown { origin , universe : self . universe () }) . vid ; ty :: Const :: new_var (self . tcx , const_var_id) . into () } } } # [doc = " Given a set of generics defined on a type or impl, returns the generic parameters mapping"] # [doc = " each type/region parameter to a fresh inference variable."] pub fn fresh_args_for_item (& self , span : Span , def_id : DefId) -> GenericArgsRef < 'tcx > { GenericArgs :: for_item (self . tcx , def_id , | param , _ | self . var_for_def (span , param)) } # [doc = " Returns `true` if errors have been reported since this infcx was"] # [doc = " created. This is sometimes used as a heuristic to skip"] # [doc = " reporting errors that often occur as a result of earlier"] # [doc = " errors, but where it's hard to be 100% sure (e.g., unresolved"] # [doc = " inference variables, regionck errors)."] # [must_use = "this method does not have any side effects"] pub fn tainted_by_errors (& self) -> Option < ErrorGuaranteed > { self . tainted_by_errors . get () } # [doc = " Set the \"tainted by errors\" flag to true. We call this when we"] # [doc = " observe an error from a prior pass."] pub fn set_tainted_by_errors (& self , e : ErrorGuaranteed) { debug ! ("set_tainted_by_errors(ErrorGuaranteed)") ; self . tainted_by_errors . set (Some (e)) ; } pub fn region_var_origin (& self , vid : ty :: RegionVid) -> RegionVariableOrigin { let mut inner = self . inner . borrow_mut () ; let inner = & mut * inner ; inner . unwrap_region_constraints () . var_origin (vid) } # [doc = " Clone the list of variable regions. This is used only during NLL processing"] # [doc = " to put the set of region variables into the NLL region context."] pub fn get_region_var_infos (& self) -> VarInfos { let inner = self . inner . borrow () ; assert ! (! UndoLogs ::< UndoLog <'_ >>:: in_snapshot (& inner . undo_log)) ; let storage = inner . region_constraint_storage . as_ref () . expect ("regions already resolved") ; assert ! (storage . data . is_empty () , "{:#?}" , storage . data) ; storage . var_infos . clone () } pub fn has_opaque_types_in_storage (& self) -> bool { ! self . inner . borrow () . opaque_type_storage . is_empty () } # [instrument (level = "debug" , skip (self) , ret)] pub fn take_opaque_types (& self) -> Vec < (OpaqueTypeKey < 'tcx > , OpaqueHiddenType < 'tcx >) > { self . inner . borrow_mut () . opaque_type_storage . take_opaque_types () . collect () } # [instrument (level = "debug" , skip (self) , ret)] pub fn clone_opaque_types (& self) -> Vec < (OpaqueTypeKey < 'tcx > , OpaqueHiddenType < 'tcx >) > { self . inner . borrow_mut () . opaque_type_storage . iter_opaque_types () . collect () } # [inline (always)] pub fn can_define_opaque_ty (& self , id : impl Into < DefId >) -> bool { debug_assert ! (! self . next_trait_solver ()) ; match self . typing_mode () { TypingMode :: Analysis { defining_opaque_types_and_generators : defining_opaque_types , } | TypingMode :: Borrowck { defining_opaque_types } => { id . into () . as_local () . is_some_and (| def_id | defining_opaque_types . contains (& def_id)) } TypingMode :: Coherence | TypingMode :: PostBorrowckAnalysis { .. } | TypingMode :: PostAnalysis => false , } } pub fn push_hir_typeck_potentially_region_dependent_goal (& self , goal : PredicateObligation < 'tcx > ,) { let mut inner = self . inner . borrow_mut () ; inner . undo_log . push (UndoLog :: PushHirTypeckPotentiallyRegionDependentGoal) ; inner . hir_typeck_potentially_region_dependent_goals . push (goal) ; } pub fn take_hir_typeck_potentially_region_dependent_goals (& self ,) -> Vec < PredicateObligation < 'tcx > > { assert ! (! self . in_snapshot () , "cannot take goals in a snapshot") ; std :: mem :: take (& mut self . inner . borrow_mut () . hir_typeck_potentially_region_dependent_goals) } pub fn ty_to_string (& self , t : Ty < 'tcx >) -> String { self . resolve_vars_if_possible (t) . to_string () } # [doc = " If `TyVar(vid)` resolves to a type, return that type. Else, return the"] # [doc = " universe index of `TyVar(vid)`."] pub fn probe_ty_var (& self , vid : TyVid) -> Result < Ty < 'tcx > , ty :: UniverseIndex > { use self :: type_variable :: TypeVariableValue ; match self . inner . borrow_mut () . type_variables () . probe (vid) { TypeVariableValue :: Known { value } => Ok (value) , TypeVariableValue :: Unknown { universe } => Err (universe) , } } pub fn shallow_resolve (& self , ty : Ty < 'tcx >) -> Ty < 'tcx > { if let ty :: Infer (v) = * ty . kind () { match v { ty :: TyVar (v) => { let known = self . inner . borrow_mut () . type_variables () . probe (v) . known () ; known . map_or (ty , | t | self . shallow_resolve (t)) } ty :: IntVar (v) => { match self . inner . borrow_mut () . int_unification_table () . probe_value (v) { ty :: IntVarValue :: IntType (ty) => Ty :: new_int (self . tcx , ty) , ty :: IntVarValue :: UintType (ty) => Ty :: new_uint (self . tcx , ty) , ty :: IntVarValue :: Unknown => ty , } } ty :: FloatVar (v) => { match self . inner . borrow_mut () . float_unification_table () . probe_value (v) { ty :: FloatVarValue :: Known (ty) => Ty :: new_float (self . tcx , ty) , ty :: FloatVarValue :: Unknown => ty , } } ty :: FreshTy (_) | ty :: FreshIntTy (_) | ty :: FreshFloatTy (_) => ty , } } else { ty } } pub fn shallow_resolve_const (& self , ct : ty :: Const < 'tcx >) -> ty :: Const < 'tcx > { match ct . kind () { ty :: ConstKind :: Infer (infer_ct) => match infer_ct { InferConst :: Var (vid) => self . inner . borrow_mut () . const_unification_table () . probe_value (vid) . known () . unwrap_or (ct) , InferConst :: Fresh (_) => ct , } , ty :: ConstKind :: Param (_) | ty :: ConstKind :: Bound (_ , _) | ty :: ConstKind :: Placeholder (_) | ty :: ConstKind :: Unevaluated (_) | ty :: ConstKind :: Value (_) | ty :: ConstKind :: Error (_) | ty :: ConstKind :: Expr (_) => ct , } } pub fn shallow_resolve_term (& self , term : ty :: Term < 'tcx >) -> ty :: Term < 'tcx > { match term . kind () { ty :: TermKind :: Ty (ty) => self . shallow_resolve (ty) . into () , ty :: TermKind :: Const (ct) => self . shallow_resolve_const (ct) . into () , } } pub fn root_var (& self , var : ty :: TyVid) -> ty :: TyVid { self . inner . borrow_mut () . type_variables () . root_var (var) } pub fn sub_unify_ty_vids_raw (& self , a : ty :: TyVid , b : ty :: TyVid) { self . inner . borrow_mut () . type_variables () . sub_unify (a , b) ; } pub fn sub_unification_table_root_var (& self , var : ty :: TyVid) -> ty :: TyVid { self . inner . borrow_mut () . type_variables () . sub_unification_table_root_var (var) } pub fn root_const_var (& self , var : ty :: ConstVid) -> ty :: ConstVid { self . inner . borrow_mut () . const_unification_table () . find (var) . vid } # [doc = " Resolves an int var to a rigid int type, if it was constrained to one,"] # [doc = " or else the root int var in the unification table."] pub fn opportunistic_resolve_int_var (& self , vid : ty :: IntVid) -> Ty < 'tcx > { let mut inner = self . inner . borrow_mut () ; let value = inner . int_unification_table () . probe_value (vid) ; match value { ty :: IntVarValue :: IntType (ty) => Ty :: new_int (self . tcx , ty) , ty :: IntVarValue :: UintType (ty) => Ty :: new_uint (self . tcx , ty) , ty :: IntVarValue :: Unknown => { Ty :: new_int_var (self . tcx , inner . int_unification_table () . find (vid)) } } } # [doc = " Resolves a float var to a rigid int type, if it was constrained to one,"] # [doc = " or else the root float var in the unification table."] pub fn opportunistic_resolve_float_var (& self , vid : ty :: FloatVid) -> Ty < 'tcx > { let mut inner = self . inner . borrow_mut () ; let value = inner . float_unification_table () . probe_value (vid) ; match value { ty :: FloatVarValue :: Known (ty) => Ty :: new_float (self . tcx , ty) , ty :: FloatVarValue :: Unknown => { Ty :: new_float_var (self . tcx , inner . float_unification_table () . find (vid)) } } } # [doc = " Where possible, replaces type/const variables in"] # [doc = " `value` with their final value. Note that region variables"] # [doc = " are unaffected. If a type/const variable has not been unified, it"] # [doc = " is left as is. This is an idempotent operation that does"] # [doc = " not affect inference state in any way and so you can do it"] # [doc = " at will."] pub fn resolve_vars_if_possible < T > (& self , value : T) -> T where T : TypeFoldable < TyCtxt < 'tcx > > , { if let Err (guar) = value . error_reported () { self . set_tainted_by_errors (guar) ; } if ! value . has_non_region_infer () { return value ; } let mut r = resolve :: OpportunisticVarResolver :: new (self) ; value . fold_with (& mut r) } pub fn resolve_numeric_literals_with_default < T > (& self , value : T) -> T where T : TypeFoldable < TyCtxt < 'tcx > > , { if ! value . has_infer () { return value ; } let mut r = InferenceLiteralEraser { tcx : self . tcx } ; value . fold_with (& mut r) } pub fn probe_const_var (& self , vid : ty :: ConstVid) -> Result < ty :: Const < 'tcx > , ty :: UniverseIndex > { match self . inner . borrow_mut () . const_unification_table () . probe_value (vid) { ConstVariableValue :: Known { value } => Ok (value) , ConstVariableValue :: Unknown { origin : _ , universe } => Err (universe) , } } # [doc = " Attempts to resolve all type/region/const variables in"] # [doc = " `value`. Region inference must have been run already (e.g.,"] # [doc = " by calling `resolve_regions_and_report_errors`). If some"] # [doc = " variable was never unified, an `Err` results."] # [doc = ""] # [doc = " This method is idempotent, but it not typically not invoked"] # [doc = " except during the writeback phase."] pub fn fully_resolve < T : TypeFoldable < TyCtxt < 'tcx > > > (& self , value : T) -> FixupResult < T > { match resolve :: fully_resolve (self , value) { Ok (value) => { if value . has_non_region_infer () { bug ! ("`{value:?}` is not fully resolved") ; } if value . has_infer_regions () { let guar = self . dcx () . delayed_bug (format ! ("`{value:?}` is not fully resolved")) ; Ok (fold_regions (self . tcx , value , | re , _ | { if re . is_var () { ty :: Region :: new_error (self . tcx , guar) } else { re } })) } else { Ok (value) } } Err (e) => Err (e) , } } pub fn instantiate_binder_with_fresh_vars < T > (& self , span : Span , lbrct : BoundRegionConversionTime , value : ty :: Binder < 'tcx , T > ,) -> T where T : TypeFoldable < TyCtxt < 'tcx > > + Copy , { if let Some (inner) = value . no_bound_vars () { return inner ; } let bound_vars = value . bound_vars () ; let mut args = Vec :: with_capacity (bound_vars . len ()) ; for bound_var_kind in bound_vars { let arg : ty :: GenericArg < '_ > = match bound_var_kind { ty :: BoundVariableKind :: Ty (_) => self . next_ty_var (span) . into () , ty :: BoundVariableKind :: Region (br) => { self . next_region_var (RegionVariableOrigin :: BoundRegion (span , br , lbrct)) . into () } ty :: BoundVariableKind :: Const => self . next_const_var (span) . into () , } ; args . push (arg) ; } struct ToFreshVars < 'tcx > { args : Vec < ty :: GenericArg < 'tcx > > , } impl < 'tcx > BoundVarReplacerDelegate < 'tcx > for ToFreshVars < 'tcx > { fn replace_region (& mut self , br : ty :: BoundRegion) -> ty :: Region < 'tcx > { self . args [br . var . index ()] . expect_region () } fn replace_ty (& mut self , bt : ty :: BoundTy) -> Ty < 'tcx > { self . args [bt . var . index ()] . expect_ty () } fn replace_const (& mut self , bc : ty :: BoundConst) -> ty :: Const < 'tcx > { self . args [bc . var . index ()] . expect_const () } } let delegate = ToFreshVars { args } ; self . tcx . replace_bound_vars_uncached (value , delegate) } # [doc = " See the [`region_constraints::RegionConstraintCollector::verify_generic_bound`] method."] pub (crate) fn verify_generic_bound (& self , origin : SubregionOrigin < 'tcx > , kind : GenericKind < 'tcx > , a : ty :: Region < 'tcx > , bound : VerifyBound < 'tcx > ,) { debug ! ("verify_generic_bound({:?}, {:?} <: {:?})" , kind , a , bound) ; self . inner . borrow_mut () . unwrap_region_constraints () . verify_generic_bound (origin , kind , a , bound) ; } # [doc = " Obtains the latest type of the given closure; this may be a"] # [doc = " closure in the current function, in which case its"] # [doc = " `ClosureKind` may not yet be known."] pub fn closure_kind (& self , closure_ty : Ty < 'tcx >) -> Option < ty :: ClosureKind > { let unresolved_kind_ty = match * closure_ty . kind () { ty :: Closure (_ , args) => args . as_closure () . kind_ty () , ty :: CoroutineClosure (_ , args) => args . as_coroutine_closure () . kind_ty () , _ => bug ! ("unexpected type {closure_ty}") , } ; let closure_kind_ty = self . shallow_resolve (unresolved_kind_ty) ; closure_kind_ty . to_opt_closure_kind () } pub fn universe (& self) -> ty :: UniverseIndex { self . universe . get () } # [doc = " Creates and return a fresh universe that extends all previous"] # [doc = " universes. Updates `self.universe` to that new universe."] pub fn create_next_universe (& self) -> ty :: UniverseIndex { let u = self . universe . get () . next_universe () ; debug ! ("create_next_universe {u:?}") ; self . universe . set (u) ; u } # [doc = " Extract [`ty::TypingMode`] of this inference context to get a `TypingEnv`"] # [doc = " which contains the necessary information to use the trait system without"] # [doc = " using canonicalization or carrying this inference context around."] pub fn typing_env (& self , param_env : ty :: ParamEnv < 'tcx >) -> ty :: TypingEnv < 'tcx > { let typing_mode = match self . typing_mode () { ty :: TypingMode :: Analysis { defining_opaque_types_and_generators : _ } | ty :: TypingMode :: Borrowck { defining_opaque_types : _ } => { TypingMode :: non_body_analysis () } mode @ (ty :: TypingMode :: Coherence | ty :: TypingMode :: PostBorrowckAnalysis { .. } | ty :: TypingMode :: PostAnalysis) => mode , } ; ty :: TypingEnv { typing_mode , param_env } } # [doc = " Similar to [`Self::canonicalize_query`], except that it returns"] # [doc = " a [`PseudoCanonicalInput`] and requires both the `value` and the"] # [doc = " `param_env` to not contain any inference variables or placeholders."] pub fn pseudo_canonicalize_query < V > (& self , param_env : ty :: ParamEnv < 'tcx > , value : V ,) -> PseudoCanonicalInput < 'tcx , V > where V : TypeVisitable < TyCtxt < 'tcx > > , { debug_assert ! (! value . has_infer ()) ; debug_assert ! (! value . has_placeholders ()) ; debug_assert ! (! param_env . has_infer ()) ; debug_assert ! (! param_env . has_placeholders ()) ; self . typing_env (param_env) . as_query_input (value) } # [doc = " The returned function is used in a fast path. If it returns `true` the variable is"] # [doc = " unchanged, `false` indicates that the status is unknown."] # [inline] pub fn is_ty_infer_var_definitely_unchanged (& self) -> impl Fn (TyOrConstInferVar) -> bool { let inner = self . inner . try_borrow () ; move | infer_var : TyOrConstInferVar | match (infer_var , & inner) { (TyOrConstInferVar :: Ty (ty_var) , Ok (inner)) => { use self :: type_variable :: TypeVariableValue ; matches ! (inner . try_type_variables_probe_ref (ty_var) , Some (TypeVariableValue :: Unknown { .. })) } _ => false , } } # [doc = " `ty_or_const_infer_var_changed` is equivalent to one of these two:"] # [doc = "   * `shallow_resolve(ty) != ty` (where `ty.kind = ty::Infer(_)`)"] # [doc = "   * `shallow_resolve(ct) != ct` (where `ct.kind = ty::ConstKind::Infer(_)`)"] # [doc = ""] # [doc = " However, `ty_or_const_infer_var_changed` is more efficient. It's always"] # [doc = " inlined, despite being large, because it has only two call sites that"] # [doc = " are extremely hot (both in `traits::fulfill`'s checking of `stalled_on`"] # [doc = " inference variables), and it handles both `Ty` and `ty::Const` without"] # [doc = " having to resort to storing full `GenericArg`s in `stalled_on`."] # [inline (always)] pub fn ty_or_const_infer_var_changed (& self , infer_var : TyOrConstInferVar) -> bool { match infer_var { TyOrConstInferVar :: Ty (v) => { use self :: type_variable :: TypeVariableValue ; match self . inner . borrow_mut () . type_variables () . inlined_probe (v) { TypeVariableValue :: Unknown { .. } => false , TypeVariableValue :: Known { .. } => true , } } TyOrConstInferVar :: TyInt (v) => { self . inner . borrow_mut () . int_unification_table () . inlined_probe_value (v) . is_known () } TyOrConstInferVar :: TyFloat (v) => { self . inner . borrow_mut () . float_unification_table () . probe_value (v) . is_known () } TyOrConstInferVar :: Const (v) => { match self . inner . borrow_mut () . const_unification_table () . probe_value (v) { ConstVariableValue :: Unknown { .. } => false , ConstVariableValue :: Known { .. } => true , } } } } # [doc = " Attach a callback to be invoked on each root obligation evaluated in the new trait solver."] pub fn attach_obligation_inspector (& self , inspector : ObligationInspector < 'tcx >) { debug_assert ! (self . obligation_inspector . get () . is_none () , "shouldn't override a set obligation inspector") ; self . obligation_inspector . set (Some (inspector)) ; } }}}
